"""Serialize an independently completed human/model review; not a semantic self-check or author script."""
import datetime,gzip,hashlib,json,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'tools'));import verify

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(day,notes,symbols,headline_numeric,corrections=None,warnings=None):
 p=ROOT/'nonretail_drafts'/f'{day}.json';x=json.loads(p.read_text());f=ROOT/'feeds'/f'{day}.json.gz';c=ROOT/'cards'/f'{day}.json';ep=ROOT/'exclusions'/f'{day}.json'
 feed=json.loads(gzip.decompress(f.read_bytes()));by={r['id']:r for r in feed['items']};card=json.loads(c.read_text());excluded=json.loads(ep.read_text())
 failures,actual_warnings,n_sources,words=verify.verify(day,nonretail=True)
 assert not failures,failures
 warnings=warnings or [];assert [z['warning'] for z in warnings]==actual_warnings
 parts=list(verify.paragraphs(x,include_retail=False));ranges=verify.block_ranges(x,include_retail=False)
 assert len(ranges)==36 and all(r['in_range'] for r in ranges)
 blocks=list(dict.fromkeys(b for b,l,t in parts));assert set(notes)==set(blocks),(set(notes)-set(blocks),set(blocks)-set(notes))
 cited=sorted(set(re.findall(r'\[\[(n\d+)\]\]',json.dumps(x))))
 assert len(cited)==n_sources and all(i in by for i in cited)
 part_checks=[]
 for b,l,t in parts:
  ids=list(dict.fromkeys(re.findall(r'\[\[(n\d+)\]\]',t)))
  part_checks.append({'block':b,'label':l,'text_sha256':hashlib.sha256(t.encode()).hexdigest(),'cited_ids':ids,'full_prose_and_full_cited_headlines_read':True,'claim_disposition':'supported headline/card facts with conditional analysis; no unresolved factual claim','block_specific_rationale':notes[b]})
 result={'schema':'june-independent-nonretail-claim-review-v1','date':day,'status':'accepted','fatal_or_major_remaining':0,'reviewer':'/root/june_provenance — independent of original author','reviewed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'nonretail_content_sha256':hashlib.sha256(json.dumps(x,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest(),'nonretail_draft_file_sha256':sha(p),'feed_sha256':sha(f),'card_sha256':sha(c),'exclusions_sha256':sha(ep),'source_freeze_sha256':sha(ROOT/'audit/source_freeze.json'),'independent_source_review_sha256':sha(ROOT/'audit/independent_source_review.json'),'reviewed_scope':{'blocks':len(ranges),'prose_parts':len(parts),'body_words':words,'distinct_sources':n_sources,'every_full_cited_headline_read':True,'all_prose_parts_read':True,'own_date_evidence_only':True,'later_drafts_or_outcomes_used':False,'source_feed_card_or_exclusions_changed':False,'major_premise_contamination':False},'verification':{'failures':failures,'raw_warnings':actual_warnings,'all_block_ranges_passed':True},'reviewed_validation_warnings':warnings,'block_ranges':ranges,'block_claim_reviews':[{'block':b,'rationale':notes[b]} for b in blocks],'paragraph_checks':part_checks,'full_cited_headline_checks':[{'id':i,'title':by[i]['title'],'src':by[i]['src'],'published_at':by[i]['published_at'],'category':by[i]['cat'],'disposition':'Full headline read; referenced concrete claim and meaning-based age/window checked in its prose context'} for i in cited],'numeric_checks':{'method':'Every numeric passage was read in context and checked against the named exact card instrument/field, source headline value, observation horizon, unit and session. Card rows below retain the inspected exact price/return bases; unused row fields are context, not additional report claims. No numeric spot FX or invented ratio/target.','card_rows_inspected':{s:card['markets'][s] for s in symbols},'treasury_fields_inspected':card['treasury'],'headline_values':headline_numeric,'market_observation_semantics':'Regular cash/futures exchange-local completed sessions; crypto prior completed UTC daily close; levels use card as-traded share units and returns use comparable split-adjusted closes excluding dividends.'},'semantic_checks':{'issuer_roles_and_event_stages':'Acquisition/distribution/approval/order-discussion and official/publisher/analyst roles checked against each full cited headline; projected benefits remain conditional.','prices_not_flows':'Price and ETF return data are not represented as observed fund flows, credit spreads or realized fundamental changes.','wide_commentary':'Every block read for specific supported tension, causal transmission and actionable conditional trigger; no raw input-management asides or ungrounded prose padding accepted.','sector_scope':'All thirteen sector blocks inspected; Polish-company coverage remains in the PL block rather than sector deep dives.','cutoff_and_window':'Completed premises checked against strictly pre-own-date 00:00 UTC evidence and current own-date exclusions; pending previews kept prospective and seven-day meaning respected.'},'precise_corrections':corrections or [],'review_tool_sha256':sha(Path(__file__))}
 dest=ROOT/'audit'/f'independent_nonretail_{day}.json';assert not dest.exists(),str(dest)
 dest.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({'receipt':str(dest.relative_to(ROOT)),'receipt_sha256':sha(dest),'canonical_content_sha256':result['nonretail_content_sha256'],'file_sha256':sha(p),'feed_sha256':sha(f),'card_sha256':sha(c),'exclusions_sha256':sha(ep),'words':words,'sources':n_sources,'blocks':len(ranges),'parts':len(parts),'ranges':ranges},ensure_ascii=False))
